        revert ReentrancyGuard();
    }
    _locked = 2;

    // Decode received data
    (address[] memory targets, uint256[] memory amounts) = abi.decode(data, (address[], uint256[]));

    uint256 batchNonce = stakingBatchNonce;
    uint256 localWithheldAmount = 0;

