function redeem(address target, uint256 amount, uint256 batchNonce) external {
    // Reentrancy guard
    if (_locked > 1) {
        revert ReentrancyGuard();
    }
    _locked = 2;

    try {
        // Pause check
        if (paused == 2) {
            revert Paused();
